/** Join literal Tailwind groups. The numeric source priority is only used
 * by PostCSS to preserve the existing cascade; it adds no browser CSS. */
export function utilities(...groups: Array<string | readonly [number, string]>): string {
  return groups.map(group => typeof group === "string" ? group : group[1]).filter(Boolean).join(" ");
}

