/** Resolve component-local state hooks to statically discoverable Tailwind utilities. */
export function resolveClasses(value: string | undefined | null | false, componentUtilities: Record<string, string> = {}): string {
  if (!value) return "";
  const tokens = value.trim().split(/\s+/);
  const present = new Set(tokens);
  for (const token of tokens) {
    for (const utility of (componentUtilities[token] || "").split(" ")) {
      if (utility) present.add(utility);
    }
  }
  return Array.from(present).join(" ");
}

const unitless = new Set([
  "animation-iteration-count", "aspect-ratio", "border-image-outset", "border-image-slice", "border-image-width",
  "box-flex", "box-flex-group", "box-ordinal-group", "column-count", "columns", "fill-opacity", "flex", "flex-grow",
  "flex-negative", "flex-order", "flex-positive", "flex-shrink", "flood-opacity", "font-weight", "grid-area",
  "grid-column", "grid-column-end", "grid-column-start", "grid-row", "grid-row-end", "grid-row-start", "line-clamp",
  "line-height", "opacity", "order", "orphans", "scale", "stop-opacity", "stroke-dasharray", "stroke-dashoffset",
  "stroke-miterlimit", "stroke-opacity", "stroke-width", "tab-size", "widows", "z-index", "zoom", "-webkit-line-clamp",
]);


const shorthands: Record<string, readonly string[]> = {
  margin: ["margin-top", "margin-right", "margin-bottom", "margin-left", "margin-inline", "margin-block"],
  padding: ["padding-top", "padding-right", "padding-bottom", "padding-left", "padding-inline", "padding-block"],
  border: ["border-top", "border-right", "border-bottom", "border-left", "border-width", "border-style", "border-color"],
  background: ["background-color", "background-image", "background-position", "background-size", "background-repeat", "background-attachment", "background-origin", "background-clip"],
  font: ["font-family", "font-size", "font-weight", "font-style", "font-stretch", "font-variant", "line-height"],
  flex: ["flex-grow", "flex-shrink", "flex-basis"],
  gap: ["row-gap", "column-gap"],
  overflow: ["overflow-x", "overflow-y"],
  inset: ["top", "right", "bottom", "left", "inset-inline", "inset-block"],
  outline: ["outline-width", "outline-style", "outline-color"],
  animation: ["animation-name", "animation-duration", "animation-delay", "animation-iteration-count", "animation-direction", "animation-fill-mode", "animation-play-state", "animation-timing-function"],
  transition: ["transition-property", "transition-duration", "transition-delay", "transition-timing-function"],
};
function overlapping(a: string, b: string): boolean {
  if (a === b || a === "all" || b === "all") return true;
  const first = shorthands[a] || [a], second = shorthands[b] || [b];
  if (first.some(x => second.includes(x)) || first.includes(b) || second.includes(a)) return true;
  return /^border-(top|right|bottom|left)$/.test(a) && b.startsWith(a + "-") || /^border-(top|right|bottom|left)$/.test(b) && a.startsWith(b + "-");
}

const propertyName = (key: string) => key.startsWith("--") ? key : key.replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`).replace(/^ms-/, "-ms-");

/**
 * Values selected by the CMS (prices, image URLs, widths, ordering, colors)
 * travel through CSS variables; their actual styling is compiled Tailwind.
 * Absent values emit no utility, preserving the component's normal fallback.
 */
export function withTailwindStyle(className: string | undefined, input: CSSProperties | undefined | null) {
  const classes = [className || ""];
  const variables: Record<string, string | number> = {};
  let index = 0;
  let group: string[] = [];
  for (const [key, raw] of Object.entries(input || {})) {
    if (raw === undefined || raw === null || typeof raw === "boolean" || raw === "") continue;
    const property = propertyName(key);
    if (property.startsWith("--")) {
      variables[property] = raw as string | number;
      continue;
    }
    if (group.some(previous => overlapping(previous, property))) { index++; group = []; }
    group.push(property);
    const utility = styleUtilities[property]?.[index];
    if (!utility) {
      // CMS-authored properties not used by the application's own design remain editable.
      variables[key] = raw as string | number;
      continue;
    }
    const value = typeof raw === "number" && raw !== 0 && !unitless.has(property) ? `${raw}px` : String(raw).trim();
    variables[`--style-${property.replace(/^-+/, "")}`] = value;
    classes.push(utility);
  }
  return { className: classes.join(" "), style: variables as CSSProperties };
}

const escapeAttribute = (value: string) => value.replaceAll("&", "&amp;").replaceAll('"', "&quot;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
const decodeAttribute = (value: string) => value.replace(/&quot;/g, '"').replace(/&#(?:0*39|x0*27);/gi, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");

function parseDeclarations(value: string) {
  const result: Array<[string, string]> = [];
  let start = 0, depth = 0, quote = "";
  for (let i = 0; i <= value.length; i++) {
    const character = value[i];
    if (quote) { if (character === quote && value[i - 1] !== "\\") quote = ""; continue; }
    if (character === '"' || character === "'") { quote = character; continue; }
    if (character === "(") depth++;
    if (character === ")") depth--;
    if (i === value.length || character === ";" && !depth) {
      const item = value.slice(start, i), colon = item.indexOf(":");
      if (colon > 0) result.push([item.slice(0, colon).trim(), item.slice(colon + 1).trim()]);
      start = i + 1;
    }
  }
  return result;
}

/** Expand already-sanitized CMS/invoice markup without altering its stored data. */
export function tailwindHtml(html: string, componentUtilities: Record<string, string> = {}): string {
  return html.replace(/<[a-z](?:"[^"]*"|'[^']*'|[^'">])*>/gi, tag => {
    const classMatch = tag.match(/\sclass\s*=\s*(["'])(.*?)\1/i);
    const styleMatch = tag.match(/\sstyle\s*=\s*(["'])(.*?)\1/i);
    let classes = resolveClasses(classMatch ? decodeAttribute(classMatch[2]) : "", componentUtilities);
    if (styleMatch) {
      const variables: Array<[string, string]> = [];
      let index = 0;
      let group: string[] = [];
      const declarations = parseDeclarations(decodeAttribute(styleMatch[2]));
      const seen = new Map<string, boolean>();
      const retained: Array<[string, string]> = [];
      for (const [property, raw] of [...declarations].reverse()) {
        const important = /!important\s*$/i.test(raw);
        const later = seen.get(property);
        if (later === true || later === false && !important) continue;
        if (important && later === false) {
          const weaker = retained.findIndex(([name]) => name === property);
          if (weaker >= 0) retained.splice(weaker, 1);
        }
        seen.set(property, important);
        retained.unshift([property, raw]);
      }
      for (const [property, raw] of retained) {
        if (group.some(previous => overlapping(previous, property))) { index++; group = []; }
        group.push(property);
        const utility = styleUtilities[property]?.[index];
        if (utility && !property.startsWith("--")) {
          const important = /!important\s*$/i.test(raw);
          classes += ` ${important ? importantStyleUtilities[property][index] : utility}`;
          variables.push([`--style-${property.replace(/^-+/, "")}`, raw.replace(/!important\s*$/i, "").trim()]);
        } else variables.push([property, raw]);
      }
      tag = tag.replace(styleMatch[0], ` style="${escapeAttribute(variables.map(([key, value]) => `${key}:${value}`).join(";"))}"`);
    }
    if (classes) {
      const replacement = ` class="${escapeAttribute(classes.trim())}"`;
      tag = classMatch ? tag.replace(classMatch[0], replacement) : tag.replace(/\s*\/?>$/, ending => replacement + ending);
    }
    return tag;
  });
}
